function identity<T>(value: T): T {
    return value;
}

const name = identity("Hen"); // string
const age = identity(47); // number

function getById<T extends { id: string }>(
    items: T[],
    id: string
): T | undefined {
    return items.find(item => item.id === id);
}

function getProperty<T, K extends keyof T>(
    obj: T,
    key: K
): T[K] {
    return obj[key];
}

function foo<T>(value: T): any {
    return value;
}

function printLength<T>(value: T) {
    return value.length;
    // Error: not every T has length
}

function printLength<T extends { length: number }>(
    value: T
): number {
    return value.length;
}
